package local.z6panel;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.graphics.drawable.*;
import android.os.*;
import android.util.LruCache;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;
import java.util.concurrent.*;

/** Six visible photos; focus previews, OK uses or marks. No full-screen navigation. */
final class WallpaperInlineGallery {
 interface Host {void preview(String id);void use(String id);void applyPresentation(boolean all,Set<String> ids);void order();void removed(String message);}
 private final Activity activity;private final WallpaperStore store;private final SharedPreferences prefs;private final Host host;
 private final Handler ui=new Handler(Looper.getMainLooper());
 private final ThreadPoolExecutor worker=new ThreadPoolExecutor(1,1,10,TimeUnit.SECONDS,new ArrayBlockingQueue<>(12),r->new Thread(()->{android.os.Process.setThreadPriority(10);r.run();},"Z6-inline-photos"));
 private final LruCache<String,Bitmap> cache=new LruCache<String,Bitmap>(4*1024*1024){protected int sizeOf(String id,Bitmap b){return b.getAllocationByteCount();}protected void entryRemoved(boolean e,String k,Bitmap old,Bitmap next){if(old!=next&&!old.isRecycled())old.recycle();}};
 private final Map<String,View> actions=new LinkedHashMap<>();private final Map<String,View> cards=new LinkedHashMap<>();private final List<ImageView> images=new ArrayList<>();
 private final Set<String> chosen=new LinkedHashSet<>(),deleting=new LinkedHashSet<>();
 private java.util.List<WallpaperStore.Photo> photos=Collections.emptyList();private LinearLayout root,grid,photoTools,slideTools;private FrameLayout timingFrame;private TextView photoHelp;private TextView hint,pages;private Button select,remove,apply,all,interval;
 private String mode="",focus="";private int offset,epoch;private boolean reusable,initialFocus,visible,busy,selecting,allPhotos=true,selectionLoaded;private AlertDialog confirmation;
 WallpaperInlineGallery(Activity a,WallpaperStore s,Host h){activity=a;store=s;host=h;prefs=a.getSharedPreferences("panel",0);worker.allowCoreThreadTimeOut(true);}
 private int dp(int n){return Math.round(n*activity.getResources().getDisplayMetrics().density);}
 private TextView text(String s,int size){TextView t=new TextView(activity);t.setText(s);t.setTextSize(size);t.setTextColor(0xFFBCC5CE);return t;}
 private GradientDrawable bg(boolean focused,boolean checked){GradientDrawable d=new GradientDrawable();d.setColor(checked?0xFF284B42:0xFF222E38);d.setCornerRadius(dp(5));if(focused)d.setStroke(dp(2),0xFFD2DFE5);return d;}
 private void style(View v){StateListDrawable d=new StateListDrawable();d.addState(new int[]{android.R.attr.state_focused},bg(true,false));d.addState(new int[]{},bg(false,false));v.setBackground(d);v.setFocusable(true);v.setId(View.generateViewId());}
 private Button button(LinearLayout row,String id,String label,Runnable action){Button b=new Button(activity);b.setText(label);b.setTextSize(12);b.setAllCaps(false);b.setTextColor(-1);b.setPadding(dp(4),0,dp(4),0);style(b);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(35),1);p.setMargins(dp(2),0,dp(2),dp(4));row.addView(b,p);actions.put(id,b);b.setOnClickListener(v->{if(!busy)action.run();});return b;}
 void setPhotos(java.util.List<WallpaperStore.Photo> list){if(busy)return;boolean same=photos.size()==list.size();for(int i=0;same&&i<photos.size();i++)same=photos.get(i).id.equals(list.get(i).id);if(same)return;photos=new ArrayList<>(list);Set<String> valid=new HashSet<>();for(WallpaperStore.Photo p:photos)valid.add(p.id);chosen.retainAll(valid);deleting.retainAll(valid);if(visible)draw();}
 View show(String value){if(reusable&&root!=null){if(!value.equals(mode)){mode=value;selecting=false;deleting.clear();}visible=true;boolean missing=false;for(String id:cards.keySet())if(cache.get(id)==null)missing=true;if(missing)draw();else refresh();return root;}hide();visible=true;if(!value.equals(mode)){mode=value;offset=0;initialFocus=initialFocus||focus.isEmpty();selecting=false;deleting.clear();}if(!selectionLoaded){allPhotos=prefs.getBoolean(WallpaperSelection.ALL,true);chosen.addAll(prefs.getStringSet(WallpaperSelection.IDS,Collections.emptySet()));selectionLoaded=true;}
  root=new LinearLayout(activity);root.setOrientation(1);actions.clear();hint=text("",12);root.addView(hint,new LinearLayout.LayoutParams(-1,dp(28)));photoTools=new LinearLayout(activity);slideTools=new LinearLayout(activity);root.addView(photoTools);root.addView(slideTools);
  select=button(photoTools,"select","Seleccionar",()->{selecting=!selecting;deleting.clear();refresh();});remove=button(photoTools,"delete","Eliminar foto",()->confirm(selecting?new ArrayList<>(deleting):focus.isEmpty()?Collections.emptyList():Collections.singletonList(focus)));button(photoTools,"delete_all","Eliminar todas",()->{ArrayList<String> ids=new ArrayList<>();for(WallpaperStore.Photo p:photos)ids.add(p.id);confirm(ids);});
  all=button(slideTools,"all","",()->{allPhotos=!allPhotos;if(!allPhotos){chosen.clear();for(WallpaperStore.Photo p:photos)chosen.add(p.id);}refresh();});apply=button(slideTools,"apply","Usar presentación",()->host.applyPresentation(allPhotos,new LinkedHashSet<>(chosen)));button(slideTools,"order","Ordenar",host::order);
  timingFrame=new FrameLayout(activity);root.addView(timingFrame,new LinearLayout.LayoutParams(-1,dp(39)));LinearLayout timing=new LinearLayout(activity);timingFrame.addView(timing,new FrameLayout.LayoutParams(-1,-1));interval=button(timing,"interval","",()->{});photoHelp=text("Sin papelera · Eliminar libera espacio",11);photoHelp.setGravity(Gravity.CENTER_VERTICAL);timingFrame.addView(photoHelp,new FrameLayout.LayoutParams(-1,-1));interval.setOnKeyListener((v,key,e)->{if(!mode.equals("slideshow")||e.getAction()!=0||(key!=21&&key!=22))return false;int[] values={5,15,30,60};int at=0,current=prefs.getInt("wallpaper_minutes",30);for(int i=0;i<4;i++)if(values[i]==current)at=i;int next=Math.max(0,Math.min(3,at+(key==22?1:-1)));prefs.edit().putInt("wallpaper_minutes",values[next]).apply();refresh();return true;});
  grid=new LinearLayout(activity);grid.setOrientation(1);root.addView(grid,new LinearLayout.LayoutParams(-1,0,1));LinearLayout footer=new LinearLayout(activity);root.addView(footer);button(footer,"previous","← Anteriores",()->page(-1));pages=text("",12);pages.setGravity(Gravity.CENTER);footer.addView(pages,new LinearLayout.LayoutParams(0,dp(35),1));button(footer,"next","Siguientes →",()->page(1));draw();reusable=true;return root;
 }
 private boolean checked(String id){return mode.equals("slideshow")?(allPhotos||chosen.contains(id)):selecting&&deleting.contains(id);}
 private void refresh(){if(!visible)return;boolean slide=mode.equals("slideshow");photoTools.setVisibility(slide?View.GONE:View.VISIBLE);slideTools.setVisibility(slide?View.VISIBLE:View.GONE);interval.setVisibility(slide?View.VISIBLE:View.INVISIBLE);photoHelp.setVisibility(slide?View.INVISIBLE:View.VISIBLE);hint.setText(photos.isEmpty()?"Añade fotos desde el celular o TV/USB":mode.equals("slideshow")?"OK incluye o excluye · Usar presentación aplica":selecting?"OK marca fotos · Eliminar confirma el borrado":"Flechas previsualizan · OK usa la foto");if(all!=null&&mode.equals("slideshow")){all.setText(allPhotos?"✓ Todas las fotos":"Fotos elegidas");int n=allPhotos?photos.size():chosen.size();apply.setText("Usar presentación ("+n+")");apply.setEnabled(n>0);interval.setText("Cada "+prefs.getInt("wallpaper_minutes",30)+" min · ← →");}if(select!=null&&mode.equals("photo")){select.setText(selecting?"Cancelar selección":"Seleccionar");remove.setText(selecting?"Eliminar ("+deleting.size()+")":"Eliminar foto");remove.setEnabled(!photos.isEmpty()&&(!selecting||!deleting.isEmpty()));}for(Map.Entry<String,View> e:cards.entrySet()){e.getValue().setBackground(bg(e.getValue().hasFocus(),checked(e.getKey())));TextView label=(TextView)e.getValue().getTag();for(WallpaperStore.Photo p:photos)if(p.id.equals(e.getKey())){label.setText((checked(p.id)?"✓ ":"")+p.name);break;}}}
 private void draw(){if(!visible||grid==null)return;boolean restoreFocus=grid.hasFocus();if(restoreFocus){View anchor=actions.get(mode.equals("slideshow")?"all":"select");if(anchor!=null)anchor.requestFocus();}int token=++epoch;worker.getQueue().clear();for(ImageView v:images)v.setImageDrawable(null);images.clear();cards.clear();actions.keySet().removeIf(k->k.startsWith("photo:"));grid.removeAllViews();cache.evictAll();if(!focus.isEmpty()&&photos.stream().noneMatch(p->p.id.equals(focus)))focus="";if(initialFocus&&!photos.isEmpty()){boolean found=false;String current=prefs.getString("wallpaper_photo","");for(int i=0;i<photos.size();i++)if(photos.get(i).id.equals(current)){focus=current;offset=i/6*6;found=true;break;}if(found)initialFocus=false;}offset=Math.min(offset,Math.max(0,(photos.size()-1)/6*6));pages.setText((offset/6+1)+" / "+Math.max(1,(photos.size()+5)/6));
  if(photos.isEmpty()){TextView empty=text("No hay fotos guardadas.\nUsa Desde el celular o Desde TV o USB.",16);empty.setGravity(Gravity.CENTER);grid.addView(empty,new LinearLayout.LayoutParams(-1,-1));refresh();return;}
  for(int r=0;r<2;r++){LinearLayout row=new LinearLayout(activity);grid.addView(row,new LinearLayout.LayoutParams(-1,0,1));for(int c=0;c<3;c++){int at=offset+r*3+c;LinearLayout card=new LinearLayout(activity);card.setOrientation(1);card.setPadding(dp(4),dp(4),dp(4),dp(4));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-1,1);lp.setMargins(dp(3),dp(3),dp(3),dp(3));row.addView(card,lp);if(at>=photos.size())continue;WallpaperStore.Photo p=photos.get(at);style(card);card.setClickable(true);cards.put(p.id,card);actions.put("photo:"+p.id,card);ImageView thumb=new ImageView(activity);thumb.setScaleType(ImageView.ScaleType.FIT_CENTER);card.addView(thumb,new LinearLayout.LayoutParams(-1,0,1));images.add(thumb);TextView name=text(p.name,11);name.setSingleLine(true);name.setEllipsize(android.text.TextUtils.TruncateAt.END);card.addView(name);card.setTag(name);
   card.setOnFocusChangeListener((v,f)->{card.setBackground(bg(f,checked(p.id)));if(f){focus=p.id;host.preview(p.id);}});card.setOnClickListener(v->{focus=p.id;if(mode.equals("slideshow")){if(allPhotos){allPhotos=false;chosen.clear();for(WallpaperStore.Photo q:photos)chosen.add(q.id);}if(!chosen.add(p.id))chosen.remove(p.id);refresh();}else if(selecting){if(!deleting.add(p.id))deleting.remove(p.id);refresh();}else host.use(p.id);});
   try{worker.execute(()->{try{Bitmap b=store.thumbnail(p);ui.post(()->{if(!visible||token!=epoch){b.recycle();return;}cache.put(p.id,b);thumb.setImageBitmap(b);});}catch(Exception ignored){}});}catch(RejectedExecutionException ignored){}
  }}refresh();if(restoreFocus)enter();
 }
 private void page(int direction){int next=offset+6*direction;if(next<0||next>=photos.size())return;offset=next;focus="";initialFocus=false;draw();enter();}
 void focusPhoto(String id){focus=id;initialFocus=true;}
 void enter(){View target=cards.get(focus);if(target==null&&!cards.isEmpty())target=cards.values().iterator().next();if(target==null)target=actions.get(mode.equals("slideshow")?"all":"select");if(target!=null)target.requestFocus();}
 private void confirm(java.util.List<String> ids){if(ids.isEmpty())return;confirmation=new AlertDialog.Builder(activity).setTitle("¿Eliminar "+ids.size()+(ids.size()==1?" foto?":" fotos?")).setMessage("Se borrarán del almacenamiento de Z6, incluidas sus miniaturas. Sin papelera. Esta acción libera espacio.").setPositiveButton("Eliminar",(d,w)->{busy=true;epoch++;worker.getQueue().clear();for(ImageView v:images)v.setImageDrawable(null);cache.evictAll();host.preview("");worker.execute(()->{try{String message=store.removeMany(ids).message();java.util.List<WallpaperStore.Photo> list=store.photos();ui.post(()->{busy=false;deleting.clear();selecting=false;photos=list;chosen.retainAll(list.stream().map(p->p.id).collect(java.util.stream.Collectors.toSet()));if(visible){draw();enter();}host.removed(message);});}catch(Exception e){ui.post(()->{busy=false;if(visible)hint.setText("No se pudo completar el borrado: "+e.getMessage());});}});}).setNegativeButton("Cancelar",null).create();confirmation.show();}
 boolean back(){if(selecting){selecting=false;deleting.clear();refresh();return true;}return false;}
 void save(Bundle b){b.putString("inline.mode",mode);b.putString("inline.focus",focus);b.putInt("inline.offset",offset);b.putBoolean("inline.all",allPhotos);b.putBoolean("inline.loaded",selectionLoaded);b.putStringArrayList("inline.chosen",new ArrayList<>(chosen));}
 void restore(Bundle b){mode=b.getString("inline.mode","");focus=b.getString("inline.focus","");offset=b.getInt("inline.offset",0);allPhotos=b.getBoolean("inline.all",true);selectionLoaded=b.getBoolean("inline.loaded",false);ArrayList<String> ids=b.getStringArrayList("inline.chosen");if(ids!=null)chosen.addAll(ids);}
 void suspend(){visible=false;epoch++;if(!busy)worker.getQueue().clear();}
 void hide(){reusable=false;visible=false;epoch++;if(!busy)worker.getQueue().clear();ui.removeCallbacksAndMessages(null);for(ImageView v:images)v.setImageDrawable(null);images.clear();cache.evictAll();if(confirmation!=null)confirmation.dismiss();}
 void destroy(){hide();worker.shutdownNow();}
 JSONObject inspect()throws JSONException{JSONArray bounds=new JSONArray();for(Map.Entry<String,View> e:actions.entrySet()){View v=e.getValue();int[] xy=new int[2];v.getLocationOnScreen(xy);bounds.put(new JSONObject().put("id",e.getKey()).put("visible",v.isShown()).put("x",xy[0]).put("y",xy[1]).put("width",v.getWidth()).put("height",v.getHeight()));}return new JSONObject().put("actions",bounds).put("visible",visible).put("mode",mode).put("page",offset/6+1).put("focusId",focus).put("visibleIds",new JSONArray(cards.keySet())).put("chosen",new JSONArray(chosen)).put("all",allPhotos).put("selecting",selecting).put("deleteCount",deleting.size()).put("busy",busy).put("dialog",confirmation!=null&&confirmation.isShowing()).put("thumbnailBytes",cache.size());}
 String action(String id){if(id.equals("enter")){enter();return "OK";}if(id.startsWith("focus:")){View v=cards.get(id.substring(6));return v!=null&&v.requestFocus()?"OK":"NOT_FOUND";}if(id.equals("confirm_delete")||id.equals("cancel_delete")){if(confirmation==null||!confirmation.isShowing())return "NO_DIALOG";confirmation.getButton(id.equals("confirm_delete")?-1:-2).performClick();return "OK";}View v=actions.get(id);if(v==null)return "NOT_FOUND";if(!v.isEnabled())return "DISABLED";v.performClick();return "OK";}
}
